1	use anyhow::Result;
2	use rusqlite::{params, Connection};
3	use serde::Serialize;
4	use std::path::Path;
5	use std::time::{SystemTime, UNIX_EPOCH};
6	
7	const DEFAULT_DEDUP_WINDOW_SECS: u64 = 300;
8	
9	pub struct SessionLog {
10	    conn: Connection,
11	    session_id: String,
12	}
13	
14	#[derive(Debug, Clone, Serialize)]
15	pub struct SessionEntry {
16	    pub id: i64,
17	    pub session_id: String,
18	    pub timestamp_ms: i64,
19	    pub tool_name: String,
20	    pub tool_input_json: String,
21	    pub tool_input_hash: String,
22	    pub file_path: Option<String>,
23	    pub content_hash: Option<String>,
24	    pub token_count: Option<i64>,
25	    pub mtime_ns: Option<i64>,
26	}
27	
28	impl SessionLog {
29	    pub fn open(db_path: &Path, session_id: &str) -> Result<Self> {
30	        let conn = Connection::open(db_path)?;
31	        conn.execute_batch(
32	            "PRAGMA journal_mode=WAL;
33	             PRAGMA synchronous=NORMAL;
34	             PRAGMA busy_timeout=5000;",
35	        )?;
36	        conn.execute_batch(
37	            "CREATE TABLE IF NOT EXISTS session_tool_log (
38	                id INTEGER PRIMARY KEY AUTOINCREMENT,
39	                session_id TEXT NOT NULL,
40	                timestamp_ms INTEGER NOT NULL,
41	                tool_name TEXT NOT NULL,
42	                tool_input_json TEXT NOT NULL,
43	                tool_input_hash TEXT NOT NULL,
44	                file_path TEXT,
45	                content_hash TEXT,
46	                token_count INTEGER,
47	                mtime_ns INTEGER
48	            );
49	
50	            CREATE INDEX IF NOT EXISTS idx_session_tool_log_session_file
51	                ON session_tool_log(session_id, file_path, timestamp_ms DESC);
52	
53	            CREATE INDEX IF NOT EXISTS idx_session_tool_log_session_time
54	                ON session_tool_log(session_id, timestamp_ms DESC);
55	
56	            CREATE INDEX IF NOT EXISTS idx_session_tool_log_session_hash
57	                ON session_tool_log(session_id, tool_input_hash);",
58	        )?;
59	        Ok(Self {
60	            conn,
61	            session_id: session_id.to_string(),
62	        })
63	    }
64	
65	    pub fn record_pre(
66	        &self,
67	        tool_name: &str,
68	        tool_input_json: &str,
69	        file_path: Option<&str>,
70	    ) -> Result<i64> {
71	        let now = now_ms();
72	        let input_hash = blake3::hash(tool_input_json.as_bytes())
73	            .to_hex()
74	            .to_string();
75	        self.conn.execute(
76	            "INSERT INTO session_tool_log
77	             (session_id, timestamp_ms, tool_name, tool_input_json, tool_input_hash, file_path)
78	             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
79	            params![
80	                self.session_id,
81	                now,
82	                tool_name,
83	                tool_input_json,
84	                input_hash,
85	                file_path,
86	            ],
87	        )?;
88	        Ok(self.conn.last_insert_rowid())
89	    }
90	
91	    pub fn record_post(
92	        &self,
93	        row_id: i64,
94	        content_hash: &str,
95	        token_count: i64,
96	        mtime_ns: Option<i64>,
97	    ) -> Result<()> {
98	        self.conn.execute(
99	            "UPDATE session_tool_log
100	             SET content_hash = ?1, token_count = ?2, mtime_ns = ?3
101	             WHERE id = ?4",
102	            params![content_hash, token_count, mtime_ns, row_id],
103	        )?;
104	        Ok(())
105	    }
106	
107	    pub fn last_read(&self, file_path: &str) -> Result<Option<SessionEntry>> {
108	        let result = self.conn.query_row(
109	            "SELECT id, session_id, timestamp_ms, tool_name, tool_input_json,
110	                    tool_input_hash, file_path, content_hash, token_count, mtime_ns
111	             FROM session_tool_log
112	             WHERE session_id = ?1 AND file_path = ?2 AND content_hash IS NOT NULL
113	             ORDER BY timestamp_ms DESC LIMIT 1",
114	            params![self.session_id, file_path],
115	            |row| {
116	                Ok(SessionEntry {
117	                    id: row.get(0)?,
118	                    session_id: row.get(1)?,
119	                    timestamp_ms: row.get(2)?,
120	                    tool_name: row.get(3)?,
121	                    tool_input_json: row.get(4)?,
122	                    tool_input_hash: row.get(5)?,
123	                    file_path: row.get(6)?,
124	                    content_hash: row.get(7)?,
125	                    token_count: row.get(8)?,
126	                    mtime_ns: row.get(9)?,
127	                })
128	            },
129	        );
130	        match result {
131	            Ok(entry) => Ok(Some(entry)),
132	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
133	            Err(e) => Err(e.into()),
134	        }
135	    }
136	
137	    pub fn recent_identical(
138	        &self,
139	        tool_input_hash: &str,
140	        within_secs: Option<u64>,
141	    ) -> Result<Option<SessionEntry>> {
142	        let window = within_secs.unwrap_or(DEFAULT_DEDUP_WINDOW_SECS);
143	        let cutoff = now_ms() - (window as i64 * 1000);
144	        let result = self.conn.query_row(
145	            "SELECT id, session_id, timestamp_ms, tool_name, tool_input_json,
146	                    tool_input_hash, file_path, content_hash, token_count, mtime_ns
147	             FROM session_tool_log
148	             WHERE session_id = ?1 AND tool_input_hash = ?2
149	                   AND timestamp_ms >= ?3 AND content_hash IS NOT NULL
150	             ORDER BY timestamp_ms DESC LIMIT 1",
151	            params![self.session_id, tool_input_hash, cutoff],
152	            |row| {
153	                Ok(SessionEntry {
154	                    id: row.get(0)?,
155	                    session_id: row.get(1)?,
156	                    timestamp_ms: row.get(2)?,
157	                    tool_name: row.get(3)?,
158	                    tool_input_json: row.get(4)?,
159	                    tool_input_hash: row.get(5)?,
160	                    file_path: row.get(6)?,
161	                    content_hash: row.get(7)?,
162	                    token_count: row.get(8)?,
163	                    mtime_ns: row.get(9)?,
164	                })
165	            },
166	        );
167	        match result {
168	            Ok(entry) => Ok(Some(entry)),
169	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
170	            Err(e) => Err(e.into()),
171	        }
172	    }
173	
174	    pub fn session_entries(&self) -> Result<Vec<SessionEntry>> {
175	        let mut stmt = self.conn.prepare(
176	            "SELECT id, session_id, timestamp_ms, tool_name, tool_input_json,
177	                    tool_input_hash, file_path, content_hash, token_count, mtime_ns
178	             FROM session_tool_log
179	             WHERE session_id = ?1
180	             ORDER BY timestamp_ms ASC",
181	        )?;
182	        let entries = stmt
183	            .query_map(params![self.session_id], |row| {
184	                Ok(SessionEntry {
185	                    id: row.get(0)?,
186	                    session_id: row.get(1)?,
187	                    timestamp_ms: row.get(2)?,
188	                    tool_name: row.get(3)?,
189	                    tool_input_json: row.get(4)?,
190	                    tool_input_hash: row.get(5)?,
191	                    file_path: row.get(6)?,
192	                    content_hash: row.get(7)?,
193	                    token_count: row.get(8)?,
194	                    mtime_ns: row.get(9)?,
195	                })
196	            })?
197	            .filter_map(|r| r.ok())
198	            .collect();
199	        Ok(entries)
200	    }
201	
202	    pub fn cleanup_old_sessions(&self) -> Result<u64> {
203	        let changes = self.conn.execute(
204	            "DELETE FROM session_tool_log
205	             WHERE session_id NOT IN (
206	                 SELECT DISTINCT session_id FROM session_tool_log
207	                 ORDER BY timestamp_ms DESC LIMIT 2
208	             )",
209	            [],
210	        )?;
211	        Ok(changes as u64)
212	    }
213	
214	    pub fn session_id(&self) -> &str {
215	        &self.session_id
216	    }
217	}
