219	pub fn extract_file_path(tool_name: &str, tool_input: &serde_json::Value) -> Option<String> {
220	    match tool_name {
221	        "Read" => tool_input
222	            .get("file_path")
223	            .and_then(|v| v.as_str())
224	            .map(|s| s.to_string()),
225	        "Grep" => tool_input
226	            .get("path")
227	            .and_then(|v| v.as_str())
228	            .map(|s| s.to_string()),
229	        "Glob" => tool_input
230	            .get("path")
231	            .and_then(|v| v.as_str())
232	            .map(|s| s.to_string()),
233	        "Bash" => {
234	            let cmd = tool_input.get("command").and_then(|v| v.as_str())?;
235	            let parts: Vec<&str> = cmd.split_whitespace().collect();
236	            if parts.len() >= 2 {
237	                let stem = std::path::Path::new(parts[0])
238	                    .file_stem()
239	                    .and_then(|s| s.to_str())
240	                    .unwrap_or(parts[0]);
241	                if matches!(stem, "cat" | "head" | "tail") {
242	                    return Some(parts[1].to_string());
243	                }
244	            }
245	            None
246	        }
247	        _ => None,
248	    }
249	}
250	
251	fn now_ms() -> i64 {
252	    SystemTime::now()
253	        .duration_since(UNIX_EPOCH)
254	        .unwrap_or_default()
255	        .as_millis() as i64
256	}
