1	use std::time::{SystemTime, UNIX_EPOCH};
2	
3	use crate::session::SessionLog;
4	
5	const DEFAULT_WINDOW_SECS: u64 = 300;
6	
7	pub struct ReadDedup<'a> {
8	    session_log: &'a SessionLog,
9	    window_secs: u64,
10	}
11	
12	pub enum ReadDedupResult {
13	    Hit {
14	        context_message: String,
15	        tokens_saved: u64,
16	    },
17	    Miss,
18	}
19	
20	impl<'a> ReadDedup<'a> {
21	    pub fn new(session_log: &'a SessionLog, window_secs: Option<u64>) -> Self {
22	        Self {
23	            session_log,
24	            window_secs: window_secs.unwrap_or(DEFAULT_WINDOW_SECS),
25	        }
26	    }
27	
28	    pub fn check_read(&self, file_path: &str) -> ReadDedupResult {
29	        let entry = match self.session_log.last_read(file_path) {
30	            Ok(Some(e)) => e,
31	            _ => return ReadDedupResult::Miss,
32	        };
33	
34	        let now_ms = now_ms();
35	        let age_secs = (now_ms - entry.timestamp_ms).max(0) / 1000;
36	        if self.window_secs == 0 || age_secs > self.window_secs as i64 {
37	            return ReadDedupResult::Miss;
38	        }
39	
40	        let stored_mtime = match entry.mtime_ns {
41	            Some(m) => m,
42	            None => return ReadDedupResult::Miss,
43	        };
44	
45	        let current_mtime = match get_file_mtime_ns(file_path) {
46	            Some(m) => m,
47	            None => return ReadDedupResult::Miss,
48	        };
49	
50	        if stored_mtime != current_mtime {
51	            return ReadDedupResult::Miss;
52	        }
53	
54	        let tokens = entry.token_count.unwrap_or(0) as u64;
55	        let context_message = format!(
56	            "File {} (~{} tokens) was read {}s ago this session. \
57	             Content unchanged (mtime verified). \
58	             Proceeding will re-send the full file content.",
59	            file_path, tokens, age_secs
60	        );
61	
62	        ReadDedupResult::Hit {
63	            context_message,
64	            tokens_saved: tokens,
65	        }
66	    }
67	
68	    pub fn check_grep(&self, tool_input_json: &str) -> ReadDedupResult {
69	        self.check_identical_tool(tool_input_json, "Grep")
70	    }
71	
72	    pub fn check_glob(&self, tool_input_json: &str) -> ReadDedupResult {
73	        self.check_identical_tool(tool_input_json, "Glob")
74	    }
75	
76	    fn check_identical_tool(&self, tool_input_json: &str, tool_kind: &str) -> ReadDedupResult {
77	        let hash = blake3::hash(tool_input_json.as_bytes())
78	            .to_hex()
79	            .to_string();
80	
81	        let entry = match self
82	            .session_log
83	            .recent_identical(&hash, Some(self.window_secs))
84	        {
85	            Ok(Some(e)) => e,
86	            _ => return ReadDedupResult::Miss,
87	        };
88	
89	        let now_ms = now_ms();
90	        let age_secs = (now_ms - entry.timestamp_ms).max(0) / 1000;
91	        let tokens = entry.token_count.unwrap_or(0) as u64;
92	
93	        let context_message = format!(
94	            "{} was run {}s ago this session with identical parameters. \
95	             Results unchanged. Previous result was ~{} tokens.",
96	            tool_kind, age_secs, tokens
97	        );
98	
99	        ReadDedupResult::Hit {
100	            context_message,
101	            tokens_saved: tokens,
102	        }
103	    }
104	}
105	
106	fn now_ms() -> i64 {
107	    SystemTime::now()
108	        .duration_since(UNIX_EPOCH)
109	        .unwrap_or_default()
110	        .as_millis() as i64
111	}
112	
113	fn get_file_mtime_ns(path: &str) -> Option<i64> {
114	    let meta = std::fs::metadata(path).ok()?;
115	    let modified = meta.modified().ok()?;
116	    let duration = modified.duration_since(UNIX_EPOCH).ok()?;
117	    Some(duration.as_nanos() as i64)
118	}
