134	    fn create_temp_file(dir: &TempDir, name: &str, content: &str) -> String {
135	        let path = dir.path().join(name);
136	        let mut f = std::fs::File::create(&path).unwrap();
137	        f.write_all(content.as_bytes()).unwrap();
138	        f.sync_all().unwrap();
139	        path.to_string_lossy().to_string()
140	    }
