142	    #[test]
143	    fn test_check_read_miss_on_first_read() {
144	        let (log, dir) = setup();
145	        let path = create_temp_file(&dir, "test.rs", "fn main() {}");
146	        let dedup = ReadDedup::new(&log, None);
147	        assert!(matches!(dedup.check_read(&path), ReadDedupResult::Miss));
148	    }
149	
150	    #[test]
151	    fn test_check_read_hit_on_second_read() {
152	        let (log, dir) = setup();
153	        let path = create_temp_file(&dir, "test.rs", "fn main() {}");
154	
155	        let mtime_ns = get_file_mtime_ns(&path).unwrap();
156	        let row_id = log
157	            .record_pre("Read", &format!(r#"{{"file_path":"{}"}}"#, path), Some(&path))
158	            .unwrap();
159	        log.record_post(row_id, "hash1", 100, Some(mtime_ns))
160	            .unwrap();
161	
162	        let dedup = ReadDedup::new(&log, None);
163	        match dedup.check_read(&path) {
164	            ReadDedupResult::Hit {
165	                context_message,
166	                tokens_saved,
167	            } => {
168	                assert!(context_message.contains("unchanged"));
