77	                timestamp INTEGER NOT NULL,
78	                command TEXT NOT NULL,
79	                input_tokens INTEGER NOT NULL,
80	                output_tokens INTEGER NOT NULL,
81	                tokens_saved INTEGER NOT NULL,
82	                layer TEXT NOT NULL,
83	                project TEXT NOT NULL,
84	                session_id TEXT NOT NULL
85	            );"
86	        )?;
87	        conn.execute_batch(
88	            "CREATE INDEX IF NOT EXISTS idx_tracking_timestamp
89	             ON tracking_events(timestamp);"
90	        )?;
91	        Ok(Self { conn })
92	    }
93	
94	    pub fn record(&self, event: &TrackingEvent) -> Result<()> {
95	        let now = now_secs();
96	        self.conn.execute(
97	            "INSERT INTO tracking_events
98	             (timestamp, command, input_tokens, output_tokens, tokens_saved,
99	              layer, project, session_id)
100	             VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
101	            params![
102	                now as i64,
103	                event.command,
104	                event.input_tokens as i64,
105	                event.output_tokens as i64,
106	                event.tokens_saved as i64,
107	                event.layer.as_str(),
108	                event.project,
109	                event.session_id,
110	            ],
111	        )?;
112	        Ok(())
113	    }
114	
115	    pub fn stats(&self, days: Option<i64>) -> Result<Stats> {
116	        let days = days.unwrap_or(RETENTION_DAYS);
117	        let cutoff = now_secs() as i64 - (days * 86400);
118	
119	        let (total_input, total_output, total_saved, count): (i64, i64, i64, i64) = self
120	            .conn
121	            .query_row(
122	                "SELECT COALESCE(SUM(input_tokens),0), COALESCE(SUM(output_tokens),0),
123	                        COALESCE(SUM(tokens_saved),0), COUNT(*)
124	                 FROM tracking_events WHERE timestamp >= ?1",
125	                params![cutoff],
126	                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
127	            )?;
128	
129	        let savings_pct = if total_input > 0 {
130	            (total_saved as f64 / total_input as f64) * 100.0
131	        } else {
132	            0.0
133	        };
134	
135	        let mut top_stmt = self.conn.prepare(
136	            "SELECT command, SUM(tokens_saved) as saved, COUNT(*) as cnt
137	             FROM tracking_events WHERE timestamp >= ?1
138	             GROUP BY command ORDER BY saved DESC LIMIT 10",
139	        )?;
140	        let top_commands: Vec<CommandStats> = top_stmt
141	            .query_map(params![cutoff], |row| {
142	                Ok(CommandStats {
143	                    command: row.get(0)?,
144	                    saved: row.get::<_, i64>(1)? as u64,
145	                    count: row.get::<_, i64>(2)? as u64,
146	                })
147	            })?
148	            .filter_map(|r| r.ok())
149	            .collect();
150	
151	        let (comp_saved, dedup_saved, read_dedup_saved): (i64, i64, i64) = self.conn.query_row(
152	            "SELECT
153	                COALESCE(SUM(CASE WHEN layer='compression' THEN tokens_saved ELSE 0 END),0),
154	                COALESCE(SUM(CASE WHEN layer='dedup' THEN tokens_saved ELSE 0 END),0),
155	                COALESCE(SUM(CASE WHEN layer='read_dedup' THEN tokens_saved ELSE 0 END),0)
156	             FROM tracking_events WHERE timestamp >= ?1",
157	            params![cutoff],
158	            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
159	        )?;
160	
161	        Ok(Stats {
162	            total_input_tokens: total_input as u64,
163	            total_output_tokens: total_output as u64,
164	            total_saved: total_saved as u64,
165	            savings_pct,
166	            event_count: count as u64,
167	            top_commands,
168	            by_layer: LayerStats {
169	                compression_saved: comp_saved as u64,
170	                dedup_saved: dedup_saved as u64,
171	                read_dedup_saved: read_dedup_saved as u64,
172	            },
173	        })
174	    }
175	
176	    pub fn cleanup(&self) -> Result<u64> {
177	        let cutoff = now_secs() as i64 - (RETENTION_DAYS * 86400);
178	        let changes = self.conn.execute(
179	            "DELETE FROM tracking_events WHERE timestamp < ?1",
180	            params![cutoff],
181	        )?;
182	        Ok(changes as u64)
183	    }
184	}
185	
186	fn now_secs() -> u64 {
187	    SystemTime::now()
188	        .duration_since(UNIX_EPOCH)
189	        .unwrap_or_default()
190	        .as_secs()
191	}
