162	fn handle_pre_tool_use() -> anyhow::Result<()> {
163	    let input = match read_stdin() {
164	        Ok(s) => s,
165	        Err(e) => {
166	            eprintln!("[codeflow] hook health-check: stdin read failed: {}", e);
167	            println!("{{}}");
168	            return Ok(());
169	        }
170	    };
171	
172	    let parsed: serde_json::Value = match serde_json::from_str(&input) {
173	        Ok(v) => v,
174	        Err(e) => {
175	            eprintln!(
176	                "[codeflow] hook health-check: invalid JSON from Claude Code: {}",
177	                e
178	            );
179	            println!("{{}}");
180	            return Ok(());
181	        }
182	    };
183	
184	    if !parsed.is_object() {
185	        eprintln!(
186	            "[codeflow] hook health-check: expected JSON object, got {}",
187	            parsed
188	        );
189	        println!("{{}}");
190	        return Ok(());
191	    }
192	
193	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
194	        Some(name) => name,
195	        None => {
196	            println!("{{}}");
197	            return Ok(());
198	        }
199	    };
200	
201	    let tool_input = match parsed.get("tool_input") {
202	        Some(v) if v.is_object() => v,
203	        _ => {
204	            println!("{{}}");
205	            return Ok(());
206	        }
207	    };
208	
209	    // Log to session (best-effort, never blocks)
210	    let session_id = session_id();
211	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
212	    if let Ok(session_log) = open_session_log(&session_id) {
213	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
214	        if let Ok(row_id) =
215	            session_log.record_pre(tool_name, &tool_input_str, file_path.as_deref())
216	        {
217	            write_last_pre_id(row_id);
218	        }
219	    }
220	
221	    match tool_name {
222	        "Bash" => {
223	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
224	                if should_wrap(command) {
225	                    let codeflow_bin = std::env::current_exe()
226	                        .map(|p| p.to_string_lossy().to_string())
227	                        .unwrap_or_else(|_| "codeflow".to_string());
228	                    let quoted_bin = shell_quote(&codeflow_bin);
229	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
230	                    let response = serde_json::json!({
231	                        "tool_input": {
232	                            "command": rewritten
233	                        }
234	                    });
235	                    println!("{}", serde_json::to_string(&response)?);
236	                    return Ok(());
237	                }
238	            }
239	            println!("{{}}");
240	        }
241	        "Read" | "Grep" | "Glob" => {
242	            if let Ok(session_log) = open_session_log(&session_id) {
243	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
244	                    .ok()
245	                    .and_then(|v| v.parse().ok());
246	                let dedup =
247	                    codeflow_core::read_dedup::ReadDedup::new(&session_log, window_secs);
248	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
249	
250	                let result = match tool_name {
251	                    "Read" => {
252	                        if let Some(fp) = file_path.as_deref() {
253	                            dedup.check_read(fp)
254	                        } else {
255	                            codeflow_core::read_dedup::ReadDedupResult::Miss
256	                        }
257	                    }
258	                    "Grep" => dedup.check_grep(&tool_input_str),
259	                    "Glob" => dedup.check_glob(&tool_input_str),
260	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
261	                };
262	
263	                match result {
264	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
265	                        context_message,
266	                        tokens_saved,
267	                    } => {
268	                        let response = serde_json::json!({
269	                            "additionalContext": context_message
270	                        });
271	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
272	
273	                        // Track savings
274	                        if tokens_saved > 0 {
275	                            if let Ok(tracking) =
276	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
277	                            {
278	                                let _ = tracking.record(
279	                                    &codeflow_core::tracking::TrackingEvent {
280	                                        command: tool_name.to_string(),
281	                                        input_tokens: tokens_saved,
282	                                        output_tokens: 0,
283	                                        tokens_saved,
284	                                        layer:
285	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
286	                                        project: std::env::current_dir()
287	                                            .unwrap_or_default()
288	                                            .to_string_lossy()
289	                                            .to_string(),
290	                                        session_id: session_id.clone(),
291	                                    },
292	                                );
293	                            }
294	                        }
295	                        return Ok(());
296	                    }
297	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
298	                        println!("{{}}");
299	                    }
300	                }
301	            } else {
302	                println!("{{}}");
303	            }
304	        }
305	        _ => {
306	            println!("{{}}");
307	        }
308	    }
309	
310	    Ok(())
311	}
