313	fn handle_post_tool_use() -> anyhow::Result<()> {
314	    let input = match read_stdin() {
315	        Ok(s) => s,
316	        Err(_) => {
317	            println!("{{}}");
318	            return Ok(());
319	        }
320	    };
321	
322	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
323	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
324	    let tool_result = parsed
325	        .get("tool_result")
326	        .and_then(|v| v.as_str())
327	        .unwrap_or("");
328	
329	    if matches!(tool_name, Some("Read" | "Grep" | "Glob" | "Bash")) {
330	        if let Some(row_id) = read_last_pre_id() {
331	            let session_id = session_id();
332	            if let Ok(session_log) = open_session_log(&session_id) {
333	                let capped = if tool_result.len() > 1_048_576 {
334	                    &tool_result[..1_048_576]
335	                } else {
336	                    tool_result
337	                };
338	                let content_hash = blake3::hash(capped.as_bytes()).to_hex().to_string();
339	                let token_count = (tool_result.len() as i64 + 3) / 4;
340	
341	                let mtime_ns = parsed
342	                    .get("tool_input")
343	                    .and_then(|ti| {
344	                        codeflow_core::session::extract_file_path(
345	                            tool_name.unwrap_or(""),
346	                            ti,
347	                        )
348	                    })
349	                    .and_then(|fp| get_file_mtime_ns(&fp));
350	
351	                let _ = session_log.record_post(row_id, &content_hash, token_count, mtime_ns);
352	            }
353	        }
354	    }
355	
356	    println!("{{}}");
357	    Ok(())
358	}
