386	fn get_file_mtime_ns(path: &str) -> Option<i64> {
387	    let meta = std::fs::metadata(path).ok()?;
388	    let modified = meta.modified().ok()?;
389	    let duration = modified
390	        .duration_since(std::time::UNIX_EPOCH)
391	        .ok()?;
392	    Some(duration.as_nanos() as i64)
393	}
