395	fn should_wrap(command: &str) -> bool {
396	    let first_word = command.split_whitespace().next().unwrap_or("");
397	    let stem = std::path::Path::new(first_word)
398	        .file_stem()
399	        .and_then(|s| s.to_str())
400	        .unwrap_or(first_word);
401	    let wrappable = [
402	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
403	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
404	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
405	    ];
406	    wrappable.contains(&stem)
407	}
