409	fn shell_quote(s: &str) -> String {
410	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
411	        format!("'{}'", s.replace('\'', "'\\''"))
412	    } else {
413	        s.to_string()
414	    }
415	}
