425	    std::env::var("CLAUDE_SESSION_ID")
426	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
427	        .unwrap_or_else(|_| {
428	            #[cfg(unix)]
429	            let ppid = unsafe { libc::getppid() } as u32;
430	            #[cfg(not(unix))]
431	            let ppid = std::process::id();
432	            format!("local-{}", ppid)
433	        })
