6	pub fn install(global: bool) -> Result<()> {
7	    let claude_dir = paths::claude_hooks_dir();
8	    let settings_path = if global {
9	        claude_dir.join("settings.json")
10	    } else {
11	        Path::new(".claude").join("settings.json")
12	    };
13	
14	    let codeflow_bin = find_codeflow_binary();
15	
16	    check_rtk_conflict(&settings_path)?;
17	
18	    let settings = read_or_create_settings(&settings_path)?;
19	    let updated = inject_hooks(&settings, &codeflow_bin)?;
20	    write_settings(&settings_path, &updated)?;
21	
22	    let scope = if global { "global" } else { "project" };
23	    println!("✓ CODEFLOW hooks installed ({} scope)", scope);
24	    println!("  Settings: {}", settings_path.display());
25	    println!("  Binary: {}", codeflow_bin);
26	    println!("  Tools:  Bash, Read, Grep, Glob");
27	    println!();
28	    println!("Tool output will be compressed and deduplicated automatically.");
29	    println!("Run `codeflow stats` to see savings, `codeflow stats --waste` for waste analysis.");
30	
31	    Ok(())
32	}
